// THE CORE PROBLEM DSA SOLVES
// Task: check whether a value exists in a collection

// Without DSA knowledge
function containsValue_naive(arr, target) {
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) return true;
    }
    return false;
}
// Time: O(n) per lookup. With 1,000,000 items: up to 1,000,000 comparisons.

// With DSA knowledge: right data structure for the right problem
const valueSet = new Set(arr);          // build once: O(n)
function containsValue_dsa(target) {
    return valueSet.has(target);        // O(1) per lookup, always
}
// 1,000,000 items = exactly 1 operation per lookup regardless of size

// At scale with 1M items and 1M lookups:
// Naive:   up to 1,000,000,000,000 operations (could take minutes)
// DSA:     1,000,000 operations     (milliseconds)
// This gap is the difference between a feature that works and a production outage.

