// FACTORIAL: frame-by-frame call stack trace
function factorial(n) {
    if (n <= 1) return 1;              // BASE CASE: n=1 or n=0
    return n * factorial(n - 1);       // RECURSIVE CASE: smaller problem
}

// factorial(4) execution trace:
// PUSH: factorial(4)  -> waiting for factorial(3)
//   PUSH: factorial(3)  -> waiting for factorial(2)
//     PUSH: factorial(2)  -> waiting for factorial(1)
//       PUSH: factorial(1)  -> base case -> returns 1
//     POP:  factorial(2)  -> computes 2 * 1 = 2 -> returns 2
//   POP:  factorial(3)  -> computes 3 * 2 = 6 -> returns 6
// POP:  factorial(4)  -> computes 4 * 6 = 24 -> returns 24
// Time: O(n)  |  Space: O(n) [4 frames alive simultaneously at deepest point]

// FIBONACCI: introduces overlapping subproblems (foundation of Level 2 DP)
function fib(n) {
    if (n <= 1) return n;             // base cases: fib(0)=0, fib(1)=1
    return fib(n - 1) + fib(n - 2);  // two recursive branches
}
// fib(5) partial call tree:
//               fib(5)
//          fib(4)    fib(3)
//       fib(3) fib(2)  fib(2) fib(1)
// fib(2) computed 3 times. fib(3) computed twice. Redundant work.
// Time: O(2^n)  |  Space: O(n) call stack depth
// Level 2 Module 1: cache fib(2) and fib(3) -> O(n) time with memoisation

// MISSING BASE CASE: stack overflow
function broken(n) {
    return n * broken(n - 1);         // no base case -> infinite recursion
    // RangeError: Maximum call stack size exceeded
}

// PROBLEM: Given an array of integers and a target sum, return
// the indices of the two numbers that add to the target.
// Exactly one valid answer exists.

// STEP 1: CLARIFY
// Q: Can the same element be used twice? -> No, different indices required.
// Q: Are inputs always valid integers? -> Yes.
// Q: Is the array sorted? -> Not guaranteed.
// Q: Can the array be empty? -> No, exactly one solution is guaranteed.

// STEP 2: EXAMPLES (created independently)
// [2, 7, 11, 15], target=9  -> [0, 1]  (2+7=9)
// [3, 2, 4],     target=6  -> [1, 2]  (2+4=6)
// [3, 3],        target=6  -> [0, 1]  (3+3=6, same value, different indices)

// STEP 3: BRUTE FORCE
// Check every pair. O(n^2) time, O(1) space.
function twoSum_brute(nums, target) {
    for (let i = 0; i < nums.length; i++)
        for (let j = i + 1; j < nums.length; j++)
            if (nums[i] + nums[j] === target) return [i, j];
}

// STEP 4: OPTIMISE
// Bottleneck: for each element, searching the rest takes O(n) time.
// Pattern: hash map gives O(1) lookup for the complement.
// Question to ask: 'Have I seen (target - current) before?'
function twoSum_optimal(nums, target) {
    const seen = new Map();
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (seen.has(complement)) return [seen.get(complement), i];
        seen.set(nums[i], i);
    }
}

