// Internal resize simulation (what JS engine does invisibly):
class DynamicArray {
    constructor() {
        this.capacity = 1;
        this.length = 0;
        this.data = new Array(this.capacity);
    }
    push(val) {
        if (this.length === this.capacity) {
            // RESIZE: allocate double, copy all, release old
            this.capacity *= 2;
            const newData = new Array(this.capacity);
            for (let i = 0; i < this.length; i++) newData[i] = this.data[i];
            this.data = newData;
            // This single push was O(n) — but amortized over all pushes: O(1)
        }
        this.data[this.length++] = val;
    }
    get(i) { return this.data[i]; }  // always O(1)
}

