// PATTERN 1: OPPOSITE ENDS — Two Sum on sorted array
// Naive: O(n^2) nested loops checking every pair
// Two Pointer: O(n) time, O(1) space
function twoSumSorted(nums, target) {
    let left = 0, right = nums.length - 1;
    while (left < right) {
        const sum = nums[left] + nums[right];
        if (sum === target) return [left, right]; // found
        if (sum < target) left++;   // sum too small: move left pointer right
        else right--;               // sum too big:  move right pointer left
    }
    return [];
}
// [1,2,3,4,6], target=6 -> left=0(1), right=4(6): sum=7>6 -> right--
//                          left=0(1), right=3(4): sum=5<6 -> left++
//                          left=1(2), right=3(4): sum=6 == target -> [1,3]

// PATTERN 2: OPPOSITE ENDS — Valid Palindrome
function isPalindrome(s) {
    // Clean: keep only alphanumeric, lowercase
    s = s.toLowerCase().replace(/[^a-z0-9]/g, '');
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) return false;
        left++;
        right--;
    }
    return true;
}
// Time: O(n)  Space: O(n) for cleaned string
// Space-optimised: skip non-alphanumeric in-place without creating new string -> O(1) space

// PATTERN 3: SAME DIRECTION — Remove Duplicates In-Place (sorted array)
// slow pointer: position of last unique element written
// fast pointer: scanning ahead for new unique elements
function removeDuplicates(nums) {
    if (nums.length === 0) return 0;
    let slow = 0;
    for (let fast = 1; fast < nums.length; fast++) {
        if (nums[fast] !== nums[slow]) {
            slow++;
            nums[slow] = nums[fast]; // write new unique value
        }
        // if equal: fast advances, slow stays — effectively skipping duplicate
    }
    return slow + 1; // length of deduplicated prefix
}
// [0,0,1,1,1,2,2,3]: slow writes unique values in-place
// Result: [0,1,2,3,...] with slow+1 = 4 unique elements
// Time: O(n)  Space: O(1)

// FIXED-SIZE WINDOW: Maximum sum of subarray of size k
function maxSumSubarray(nums, k) {
    // Build first window
    let windowSum = 0;
    for (let i = 0; i < k; i++) windowSum += nums[i];
    let maxSum = windowSum;

    // Slide: add right element, remove left element
    for (let right = k; right < nums.length; right++) {
        windowSum += nums[right];        // expand: new element enters
        windowSum -= nums[right - k];    // shrink: old element leaves
        maxSum = Math.max(maxSum, windowSum);
    }
    return maxSum;
}
// [2,1,5,1,3,2], k=3 -> windows: [2,1,5]=8, [1,5,1]=7, [5,1,3]=9, [1,3,2]=6 -> 9
// Time: O(n)  Space: O(1)

// VARIABLE-SIZE WINDOW: Longest substring without repeating characters
function lengthOfLongestSubstring(s) {
    const charSet = new Set(); // tracks characters in current window
    let left = 0;
    let maxLen = 0;

    for (let right = 0; right < s.length; right++) {
        // Shrink window from left until no duplicate
        while (charSet.has(s[right])) {
            charSet.delete(s[left]); // remove leftmost char
            left++;                   // shrink window
        }
        charSet.add(s[right]);        // expand: add new char
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
// 'abcabcbb': right scans forward, left shrinks when duplicate found
// 'abc' -> 'a' enters again -> shrink left past 'a' -> 'bca' -> ... -> maxLen=3
// Time: O(n)  Space: O(min(n, alphabet_size))

// RECOGNITION SIGNAL:
// 'subarray/substring of size k'      -> fixed window
// 'longest/shortest satisfying X'      -> variable window
// 'contiguous elements'                -> sliding window candidate

// BUILDING A PREFIX SUM ARRAY
function buildPrefix(arr) {
    const prefix = new Array(arr.length + 1).fill(0); // dummy 0 at index 0
    for (let i = 0; i < arr.length; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }
    return prefix;
}
// arr =    [3, 1, 4, 1, 5, 9, 2, 6]
// prefix = [0, 3, 4, 8, 9, 14,23,25,31]
//           ^dummy

// RANGE SUM QUERY: O(1) after O(n) build
function rangeSum(prefix, l, r) {
    return prefix[r + 1] - prefix[l]; // sum of arr[l..r] inclusive
}
// Sum of arr[2..5] = prefix[6] - prefix[2] = 23 - 4 = 19
// Verify: arr[2]+arr[3]+arr[4]+arr[5] = 4+1+5+9 = 19 ✓

// WITHOUT PREFIX: k queries each O(n) -> O(n*k) total
// WITH PREFIX:    O(n) build + k * O(1) queries -> O(n + k) total

// APPLICATION: Subarray Sum Equals K (LeetCode #560)
// Count subarrays summing to k
function subarraySum(nums, k) {
    const countMap = new Map([[0, 1]]); // prefix sum 0 seen once (empty subarray)
    let prefixSum = 0;
    let count = 0;
    for (const num of nums) {
        prefixSum += num;
        // If (prefixSum - k) was seen before, those subarrays sum to k
        count += countMap.get(prefixSum - k) || 0;
        countMap.set(prefixSum, (countMap.get(prefixSum) || 0) + 1);
    }
    return count;
}
// Time: O(n)  Space: O(n)
// This combines prefix sums with a hash map — a Level 2 pattern preview

// STRING IMMUTABILITY — concatenation in a loop: O(n^2)
function buildString_slow(chars) {
    let result = '';
    for (const c of chars) result += c; // NEW string allocated each iteration
    return result;
}
// n iterations, iteration i copies i characters: total copies = n(n+1)/2 = O(n^2)

// CORRECT PATTERN — array join: O(n)
function buildString_fast(chars) {
    const parts = [];
    for (const c of chars) parts.push(c); // O(1) amortized each
    return parts.join('');                  // one O(n) pass
}

// CHARACTER MAP — frequency count in O(n)
function charFrequency(s) {
    const freq = {};
    for (const c of s) freq[c] = (freq[c] || 0) + 1;
    return freq;
}
