// Problem: 'Longest subarray with at most k zeros'
// Signal: 'longest' + 'contiguous subarray' + 'at most k' -> VARIABLE SLIDING WINDOW
function longestSubarrayKZeros(nums, k) {
    let left = 0, zeros = 0, maxLen = 0;
    for (let right = 0; right < nums.length; right++) {
        if (nums[right] === 0) zeros++;
        while (zeros > k) { if (nums[left++] === 0) zeros--; }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

// Problem: 'Count subarrays with product less than k'
// Signal: 'count' + 'contiguous subarray' + 'product constraint' -> SLIDING WINDOW
function numSubarrayProductLessThanK(nums, k) {
    if (k <= 1) return 0;
    let left = 0, product = 1, count = 0;
    for (let right = 0; right < nums.length; right++) {
        product *= nums[right];
        while (product >= k) product /= nums[left++];
        count += right - left + 1; // all subarrays ending at right with left<=start<=right
    }
    return count;
}

