// TWO SUM — count pairs equalling target (not indices, just count)
function countPairs(nums, target) {
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
    let count = 0;
    const counted = new Set();
    for (const [num, cnt] of freq) {
        const comp = target - num;
        if (counted.has(num)) continue; // already counted this pair
        if (comp === num) {
            count += Math.floor(cnt / 2); // pairs within same value
        } else if (freq.has(comp)) {
            count += cnt * freq.get(comp);
        }
        counted.add(num);
        counted.add(comp);
    }
    return count;
}

// THREE SUM — sort + two pointers: O(n^2) time, O(1) space
function threeSum(nums) {
    nums.sort((a, b) => a - b);
    const result = [];
    for (let i = 0; i < nums.length - 2; i++) {
        if (i > 0 && nums[i] === nums[i-1]) continue; // skip duplicates
        let left = i + 1, right = nums.length - 1;
        while (left < right) {
            const sum = nums[i] + nums[left] + nums[right];
            if (sum === 0) {
                result.push([nums[i], nums[left], nums[right]]);
                while (left < right && nums[left] === nums[left+1]) left++;  // skip dups
                while (left < right && nums[right] === nums[right-1]) right--; // skip dups
                left++; right--;
            } else if (sum < 0) left++;
            else right--;
        }
    }
    return result;
}

