        let j = i;
        while (s[j] !== '#') j++;       // scan to find '#'
        const len = Number(s.slice(i, j)); // parse length
        const str = s.slice(j + 1, j + 1 + len); // extract exactly len chars
        result.push(str);
        i = j + 1 + len;                // advance past this segment
    }
    return result;
}

