// VALID SUDOKU — three arrays of Sets: O(81) = O(1)
function isValidSudoku(board) {
    const rows  = Array.from({length: 9}, () => new Set());
    const cols  = Array.from({length: 9}, () => new Set());
    const boxes = Array.from({length: 9}, () => new Set());

    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const val = board[r][c];
            if (val === '.') continue; // empty cell — skip

            const boxIdx = Math.floor(r / 3) * 3 + Math.floor(c / 3);
            // boxIdx maps (r,c) to box 0-8:
            // (0-2,0-2)->0  (0-2,3-5)->1  (0-2,6-8)->2
            // (3-5,0-2)->3  (3-5,3-5)->4  (3-5,6-8)->5
            // (6-8,0-2)->6  (6-8,3-5)->7  (6-8,6-8)->8

            if (rows[r].has(val) || cols[c].has(val) || boxes[boxIdx].has(val)) {
                return false; // duplicate found
            }
            rows[r].add(val);
            cols[c].add(val);
            boxes[boxIdx].add(val);
        }
    }
    return true;
}

