    for (const x of arr) freq.set(x, (freq.get(x) || 0) + 1);
    return freq;
}

// PATTERN 2: COMPLEMENT LOOKUP
// Signal: find pair/triple summing to target, find matching element
// Template:
function complementLookup(arr, target) {
    const seen = new Map(); // value -> index or metadata
    for (let i = 0; i < arr.length; i++) {
        const complement = target - arr[i];
        if (seen.has(complement)) return [seen.get(complement), i];
        seen.set(arr[i], i);
    }
}

// PATTERN 3: SEEN SET
// Signal: duplicate detection, cycle detection, has x been visited
// Template:
function seenSet(arr) {
    const seen = new Set();
    for (const x of arr) {
        if (seen.has(x)) return true; // duplicate found
        seen.add(x);
    }
    return false;
}

// PATTERN 4: FINGERPRINTING
// Signal: group by equivalence, anagrams, items sharing hidden property
// Template:
function fingerprinting(items, computeKey) {
    const groups = new Map();
    for (const item of items) {
        const key = computeKey(item);
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(item);
    }
    return [...groups.values()];
}

